ST.xhtml:p:
RTrigger1(CLK := g_bZFollowSmoothExecute);

IF RTrigger1.Q THEN
  (*随动穿孔高度,穿孔时间,切割高度*) 
  g_bZFollowSmooth.PIERCEHEIGHT := g_dZFollowSmoothPierceHt;
  g_bZFollowSmooth.PIERCETIME := g_dZFollowSmoothPierceTime/1000.0;
  g_bZFollowSmooth.CUTHEIGHT := g_dZFollowSmoothCutHt;
  g_bZFollowSmoothExecute := FALSE;

  g_bZFollowSmoothPierceEnd := FALSE;
  g_bZFollowSmoothPierceStart := FALSE;
  g_bZFollowOutDone := FALSE;
  g_boZFollowOutDone := FALSE;
  nZFollowSmoothState := 1;
END_IF;

g_bZFollowSmooth.CURHEIGHT := g_fZAxisHeight;

CASE nZFollowSmoothState OF
  1:
  IF Axis_Z.NcToPlc.AxisState = 9 THEN
    g_bZFollowClose := TRUE;
    nZFollowSmoothState := 2;
  ELSE
    nZFollowSmoothState := 5;
  END_IF;
  2:
  IF Axis_Z.NcToPlc.AxisState = 2 THEN
    nZFollowSmoothState := 5;
  END_IF;  
  5:
  g_bZFollowSmooth.EXECUTE := TRUE;
  g_bZFollowSmooth.PIERCEHEIGHT := g_dZFollowSmoothPierceHt;
  g_bZFollowSmooth.CUTHEIGHT := g_dZFollowSmoothCutHt;
  IF g_bZFollowSmooth.PIERCESTART THEN  (*无感穿孔开始*)
    g_bZFollowSmoothPierceStart := TRUE;
  END_IF;
  IF g_bZFollowSmooth.PIERCEEND THEN   (*无感穿孔完成*)
    g_bZFollowSmooth.EXECUTE := FALSE;
    g_bZFollowSmoothPierceEnd := TRUE;
    nZFollowSmoothState := 0;
  ELSIF g_bZFollowSmooth.ERROR THEN
    ErrorID := g_bZFollowSmooth.ERRORID;
    g_bZFollowSmooth.EXECUTE := FALSE;
    nZFollowSmoothState := 10;
  END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nZFollowSmoothState := 0;
  g_bZFollowSmooth.Execute := FALSE;
  g_ZFollowOut.Execute := FALSE;
  g_bZFollowSmoothPierceEnd := FALSE;
  g_bZFollowSmoothPierceStart := FALSE;
  g_bZFollowSmoothExecute := FALSE;
END_IF;
